function locationCard(l,large=false){const status=missionStatus(session,l.id);return `<button class="location-card" data-action="level" data-level="${l.id}" ${session&&status.state==='locked'?'disabled':''}><span class="num">${status.state==='done'?'✓':l.id}</span><img src="${art('location-'+l.id)}" alt="" loading="lazy"><strong>${e(l.name)}</strong><small>${e(l.subtitle)}</small><span class="status">${session?status.label:'Misi '+l.id+' · 4 cabaran'} ${icon('arrow')}</span></button>`;}
function homeView(){return `<section class="hero adventure-hero"><div class="hero-copy"><span class="pill hero-kicker">${icon('shield')} TAHUN 2 · MISI IMBUHAN AWALAN</span><p class="eyebrow">Pasukan polis pembantu komuniti</p><h1 class="game-logo">OPS <em>ImAn</em></h1><h2>Jelajah bandar.<br>Jadi wira bahasa!</h2><p>Bandar Polis ImAn memerlukan bantuan kamu. Cari petunjuk, selesaikan cabaran dan kumpul enam lencana bahasa.</p><div class="btn-row">${btn('new','Mula Pengembaraan '+icon('arrow'),'gold')}${btn('tutorial',icon('help')+' Cara Bermain','hero-secondary')}${session?btn('resume','Sambung misi','hero-secondary'):''}</div><div class="hero-meta"><span>${icon('map')} 6 lokasi</span><span>${icon('star')} 24 cabaran</span><span>${icon('clock')} Ikut rentak kamu</span></div></div><div class="hero-art"><img src="${art('hero-city')}" alt="Polis lelaki dan perempuan menyambut kamu di bandar dengan balai, jalan raya, kereta peronda, motosikal dan helipad" fetchpriority="high"><div class="float-note top">${icon('star')}<span>Setiap usaha diraikan<small>Bantuan sentiasa tersedia</small></span></div><div class="float-note bottom">${icon('shield')}<span>Selamat datang, wira!<small>Bersedia membantu komuniti</small></span></div></div></section><section class="destination-section"><div class="section-title"><div><span class="eyebrow">PETA PENGEMBARAAN</span><h2>Enam lokasi. Satu misi hebat.</h2><p>Kenali bandar dan kemahiran yang akan kamu pelajari.</p></div><span class="pill">Fokus bahasa: meN-</span></div><div class="location-grid">${LEVELS.map(l=>locationCard(l)).join('')}</div></section><div class="bottom-banner"><div class="btn-row">${icon('print')}<div><strong>Bawa pengembaraan dalam beg bimbit!</strong><p>Enam aktiviti dan kit kod · 70% digital + 30% aktiviti maujud.</p></div></div>${btn('print','Teroka kit cetakan '+icon('arrow'),'outline small')}</div>`;}
function setupView(){return `<div class="narrow"><div class="center"><span class="pill">Daftar anggota baharu</span><h1 style="font-size:42px;margin:16px 0">Kenalkan diri kamu!</h1><p class="muted">Nama dan kelas membantu guru menyimpan kemajuan.</p></div><form id="setup-form" class="card"><div class="form-grid"><div class="field"><label for="student-name">Nama kamu</label><input id="student-name" name="name" type="text" maxlength="60" autocomplete="off" required placeholder="Contoh: Aisyah"></div><div class="field"><label for="student-class">Kelas</label><input id="student-class" name="className" type="text" maxlength="40" required placeholder="Contoh: 2 Bestari"></div></div><div class="field"><label>Pilih avatar kamu</label><div class="avatar-options">${['boy','girl','hijab'].map((a,i)=>`<label class="avatar-choice"><img src="assets/v2/police-${a}.png" alt="Avatar polis ${i+1}"><input type="radio" name="avatar" value="${a}" ${i===0?'checked':''}> Anggota ${['Najmi','Putri','Nabilah'][i]}</label>`).join('')}</div></div><div class="form-grid"><div class="field"><label for="mode">Mod pembelajaran</label><select id="mode" name="mode">${[['guidance','Bimbingan'],['standard','Standard'],['enrichment','Pengayaan']].map(([k,v])=>`<option value="${k}" ${data.settings.mode===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="control">Kawalan</label><select id="control" name="control"><option value="mouse">Tetikus / sentuhan</option><option value="keyboard">Papan kekunci</option><option value="hand">Gerakan tangan (kamera)</option></select></div></div><p class="help">Kamera hanya dihidupkan apabila mod tangan dipilih. Tiada akaun murid diperlukan.</p><div class="btn-row"><button class="primary" type="submit">Sedia untuk misi ${icon('arrow')}</button>${btn('home','Kembali','outline','type="button"')}</div></form></div>`;}
function mapView(){if(!session)return setupView();return `<div class="map-header"><div class="profile-chip"><img src="${avatarArt(session.avatar)}" alt="Avatar kamu"><div><strong>Hai, ${e(session.name)}!</strong><small>${e(session.className)} · Pasukan Bandar Polis ImAn</small></div></div><div class="stat-strip"><span class="stat">${icon('shield')} ${session.completedLevels.length}/6 lencana</span><span class="stat">${icon('star')} ${session.stars} bintang</span>${btn('badges','Koleksi lencana','outline small')}${certificateEligible(session)?btn('certificate-view','Lihat Sijil','primary small',`data-id="${session.id}"`):''}</div></div><div class="section-title"><div><span class="eyebrow">BANDAR POLIS IMAN</span><h2>Ke mana misi kita hari ini?</h2><p>Pilih bangunan misi. Selesaikan empat cabaran untuk membuka lokasi seterusnya.</p></div>${btn('tutorial',icon('help')+' Tutorial','outline small')}</div>${cityMap(session)}${finalBanner()}<div class="bottom-banner"><div><strong>Misi kecil hari ini</strong><p>Sasaran sesi: ${session.limit} cabaran. Kamu boleh berehat pada bila-bila masa.</p></div><div class="btn-row">${btn('review','Ulang kaji kesilapan','outline small')}${btn('overall','Lihat pencapaian','primary small')}</div></div>`;}
const mazeNow=()=>makeMaze(session.level,session.easy);
const solvedIndices=()=>[0,1,2,3].filter(i=>session.records[`P${session.level}-C${i+1}`]?.complete);
function ensurePosition(){return restoreStationPosition(session,mazeNow());}
function gameView(){if(!session){page='setup';return setupView();}const l=LEVELS[session.level-1],solved=solvedIndices();return `<div class="game-top"><div class="game-title">${btn('map',icon('map'),'icon-btn outline','aria-label="Kembali ke peta"')}<div><small>${e(session.name)} · Peringkat ${l.id}</small><h2>${e(l.name)}</h2></div></div><div class="btn-row"><span class="stat">${icon('star')} <b id="stars">${session.stars}</b></span><span class="stat">${icon('clock')} <span id="timer">${clockText(session.activeMs)}</span></span>${btn('toggle-audio',icon(session.audio?'sound':'mute'),'icon-btn outline',`aria-label="${session.audio?'Matikan':'Hidupkan'} audio"`)}${btn('pause',icon('pause'),'icon-btn primary','aria-label="Jeda permainan"')}</div></div><div class="game-layout"><div class="maze-card"><div class="maze-bar"><span id="challenge-counter">Cabaran ${Math.min(solved.length+1,4)} daripada 4 · ${e(l.subtitle)}</span><div class="progress-dots">${[0,1,2,3].map(i=>`<span class="${solved.includes(i)?'done':''}"></span>`).join('')}</div></div><div class="maze-view-tools">${btn('maze-camera',mazeCamera?'Lihat seluruh peta':'Ikut anggota polis','small outline')}${btn('city-guide','Kenali lokasi','small outline')}</div><div id="maze-holder"></div><p class="station-map-note">Pilih nombor atau objek untuk menuju cabaran. <strong>Ikut turutan 1 → 4.</strong></p><div class="maze-legend"><span><i class="dot" style="background:#ffd66a"></i>Petunjuk bergambar</span><span><i class="dot" style="background:#e4aa45"></i>Laluan misi</span><span><i class="dot" style="background:#79b5e9"></i>Tamat</span></div></div><aside class="card control-card"><h3>Gerakkan anggota polis</h3><div><div class="dpad"><button class="up" data-dir="up" aria-label="Gerak atas">↑</button><button class="left" data-dir="left" aria-label="Gerak kiri">←</button><span class="center">GERAK</span><button class="right" data-dir="right" aria-label="Gerak kanan">→</button><button class="down" data-dir="down" aria-label="Gerak bawah">↓</button></div>${btn('controls','Tukar kawalan','outline small','style="width:100%"')}<p class="subtle center" style="margin:8px 0">${{mouse:'Tetikus / sentuhan',keyboard:'Anak panah / WASD',hand:'Tuding kanta pada pad arah'}[session.control]}</p></div><div class="powers">${powerButton('path')}${btn('safe',icon('shield')+' Titik selamat','power')}${btn('tutorial',icon('help')+' Misi latihan','power')}</div><p class="help-text subtle" style="margin:8px 0 0">Cari gambar petunjuk. Jawab cabaran untuk membuka laluan. Tiada had masa.</p></aside></div><div id="hand-notice" class="notice warning" ${session.control==='hand'&&!handTracked()?'':'hidden'}>Tunjukkan tangan kamu di hadapan kamera. ${btn('mouse','Guna Tetikus','small')}</div>`;}
function drawMaze(){if(page!=='game'||!session||!$('#maze-holder'))return;const m=mazeNow(),p=ensurePosition(),solved=solvedIndices(),next=m.points.find((_,i)=>!solved.includes(i)),route=pathOn?routeTo(m,p,next?.challenge||m.end,solved):[];$('#maze-holder').innerHTML=roadMaze({maze:m,position:p,solved,route,items:currentItems().filter(i=>i.level===session.level),avatar:session.avatar,level:session.level,camera:mazeCamera});}
let navigationRun=0;
function move(dir,automatic=false){if(!automatic)navigationRun++;if(modal==='tutorial'){tutorialMove(dir);return;}if(page!=='game'||modal||!session||document.hidden||(session.control==='hand'&&!handTracked()))return;const now=performance.now();if(now-lastMove<135)return;lastMove=now;const [dx,dy]={up:[0,-1],down:[0,1],left:[-1,0],right:[1,0]}[dir]||[0,0],m=mazeNow(),p=ensurePosition(),x=p.x+dx,y=p.y+dy;if(!canMove(m,x,y,solvedIndices()))return;p.x=x;p.y=y;drawMaze();save();const pt=m.points.find(pt=>pt.challenge.x===x&&pt.challenge.y===y&&!session.records[`P${session.level}-C${pt.index+1}`]?.complete);if(pt)openQuestion(itemBy(`P${session.level}-C${pt.index+1}`));else if(x===m.end.x&&y===m.end.y&&solvedIndices().length===4)finishLevel();}
async function navigateToStation(index){
 if(page!=='game'||modal||!session)return;const m=mazeNow(),point=m.points[index];if(!point)return;
 const solved=solvedIndices();if(solved.includes(index)){openQuestion(itemBy(`P${session.level}-C${index+1}`),true);return;}
 const route=routeTo(m,ensurePosition(),point.challenge,solved);if(!route.length){notify('Selesaikan cabaran terdahulu untuk membuka laluan ini.');return;}
 const run=++navigationRun;if(route.length===1){openQuestion(itemBy(`P${session.level}-C${index+1}`));return;}
 for(const next of route.slice(1)){await new Promise(resolve=>setTimeout(resolve,160));if(run!==navigationRun||page!=='game'||modal)return;const p=ensurePosition(),oldX=p.x,oldY=p.y;move(next.x>p.x?'right':next.x<p.x?'left':next.y>p.y?'down':'up',true);if(p.x===oldX&&p.y===oldY)return;}
}
function questionImage(item,cls='question-image'){
 if(/^P[1-6]-C[1-4]$/.test(item.id)&&['reading','helping','searching','traffic'][item.index-1]===item.action)return actionScene(item.level,item.index,{className:cls+' station-question',label:item.sentence});
 return img(item.action,cls);
}
function powerButton(id){const p=POWER[id],count=session?.powers[id]??0,enabled=(session?.assist||data.settings.assist).includes(id);return `<button class="power" data-action="power" data-power="${id}" ${!enabled||count===0?'disabled':''}>${icon(p.icon)}<span>${p.name}</span><span class="count">${count}</span></button>`;}
function libraryView(){const selected=data.settings.enrichment;return `<div class="section-title"><div><span class="eyebrow">Buku kata anggota polis</span><h1 style="font-size:40px;margin:10px 0">Kenali keluarga meN-</h1><p>Perkataan asal ialah kata dasar. Perhatikan perubahan huruf.</p></div>${btn('map','Ke peta misi '+icon('arrow'),'primary small')}</div><div class="library-grid">${words().map(w=>`<article class="card library-card">${img(w.action,'')}<div class="word-arrow">Kata dasar: <b>${e(w.base)}</b></div><div class="word-parts">${wordParts(w.word,w.prefix)}</div><p class="help">${e(w.note)}</p><div class="btn-row">${audioBtn(w.note)}${btn('word-practice','Cuba padanan','outline small',`data-word="${e(w.base)}"`)}</div></article>`).join('')}</div>${selected.length?`<div class="section-title" style="margin-top:35px"><h2>Pengayaan pilihan guru</h2><span class="pill">${selected.join(' · ')}</span></div><div class="library-grid">${ENRICHMENT.filter(w=>selected.includes(w.group)).map(w=>`<article class="card library-card">${img(w.action,'')}<h3>${e(w.base)} → ${e(w.word)}</h3><p>${e(w.sentence)}</p><div class="btn-row">${audioBtn(w.sentence)}${btn('enrich','Cuba padanan','outline small',`data-word="${w.word}"`)}</div></article>`).join('')}</div>`:''}${communityGallery()}`;}
function wordParts(word,prefix){const n=prefix.replace('-','').length;return `<span class="prefix">${e(word.slice(0,n))}</span><span class="base">${e(word.slice(n))}</span>`;}
function printView(){return `<span class="eyebrow">70% digital · 30% bahan maujud</span><div class="section-title"><div><h1 style="font-size:40px;margin:12px 0">Pusat Cetakan OPS ImAn</h1><p>${printCatalog.length} bahan untuk enam aktiviti, kad kod dan Peti Kejayaan.</p></div>${btn('kit-guide','Panduan kit','outline')}</div><div class="print-toolbar"><label for="print-session">Sesi untuk cetakan</label><select id="print-session"><option value="">Set maujud umum</option>${data.sessions.map(s=>`<option value="${s.id}" ${printSessionId===s.id?'selected':''}>${e(s.name)} · ${e(s.className)}</option>`).join('')}</select><label class="check-row"><input type="checkbox" id="ink-mode" ${ink?'checked':''}> Versi jimat dakwat</label><span class="subtle">A4 & A3 · Margin selamat 10 mm · PDF sebenar</span></div><div class="notice">Pratonton menggunakan nama murid dan kandungan suntingan semasa. PDF muat turun ialah set asal; pilih Cetak → Simpan sebagai PDF untuk set tersuai.</div><div class="print-grid">${printCatalog.map((m,i)=>`<article class="card print-card"><div class="print-preview"><img src="assets/v2/${m.id.includes('maze')?'hero-city':m.id.includes('picture')||m.id.includes('challenge')?'action-reading':m.id.includes('token')||m.id==='certificate'?'police-girl':`location-${i%6+1}`}.png" alt=""></div><span class="pill ${m.teacher?'orange':''}" style="align-self:flex-start;margin-bottom:10px">${m.teacher?'Bahan guru':'Bahan murid'} · ${e(m.size)}</span><h3>${e(m.title)}</h3><p>${e(m.description)}</p><div class="btn-row">${btn('print-preview','Pratonton','primary small',`data-id="${m.id}"`)}${m.id==='mission-codes'&&printSessionId?btn('print-session-codes','PDF sesi ini','outline small'):m.id==='passport'&&printSessionId?btn('print-preview','Cetak / Simpan PDF sesi','outline small',`data-id="${m.id}"`):`<a href="assets/pdf/${m.id}${ink?'-ink':''}.pdf" download>${icon('download')} PDF set asal</a>`}</div></article>`).join('')}</div>`;}
function newSession(form){const f=Object.fromEntries(form);if(!f.name.trim()||!f.className.trim())return notify('Isi nama dan kelas dahulu.');session={id:crypto.randomUUID(),name:f.name.trim(),className:f.className.trim(),avatar:f.avatar,mode:f.mode,control:f.control,createdAt:new Date().toISOString(),completedAt:null,certificate:null,level:f.mode==='enrichment'&&Number(data.settings.startLevel)===1?4:Number(data.settings.startLevel),positions:{},records:{},stars:0,activeMs:0,levelMs:{},completedLevels:[],powers:{hint:4,radio:4,path:6,two:3,double:2},powerLog:[],practice:[],audio:true,limit:Number(data.settings.limit),cycleCount:0,easy:data.settings.easy,assist:[...data.settings.assist],targets:[...data.settings.targets],teacher:{tp:'',date:'',notes:''}};syncMissionProgress(session);data.sessions.push(session);save();go('map');showTutorial();}
function startLevel(level){if(!session){go('setup');return;}session.level=level;ensurePosition();session.cycleCount=0;go('game');if(session.control==='hand')activateHands();const p=ensurePosition(),pt=mazeNow().points.find(pt=>pt.challenge.x===p.x&&pt.challenge.y===p.y&&!session.records[`P${level}-C${pt.index+1}`]?.complete);if(pt)openQuestion(itemBy(`P${level}-C${pt.index+1}`));}
function showModal(type,html,wide=false){clearInterval(holdTimer);modal=type;$('#modal-root').innerHTML=`<div class="overlay"><section class="dialog ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${type==='question'?'Cabaran bahasa':'OPS ImAn'}" tabindex="-1">${html}</section></div>`;$('#app').inert=true;document.body.classList.add('modal-open');$('.dialog').focus({preventScroll:true});updateMusic();}
function closeModal(stop=true){if(stop)stopAudio();modal=null;$('#modal-root').innerHTML='';$('#app').inert=false;document.body.classList.remove('modal-open');updateMusic();}
function dialogHead(title,close=true){return `<div class="dialog-head"><h2>${title}</h2>${close?btn('close',icon('close'),'icon-btn','aria-label="Tutup panel"'):''}</div>`;}
function recordFor(){if(qstate.practice)return qstate.record;return session.records[qstate.item.id];}
function blankRecord(item){return {gameType:item.gameType||item.type,activeMs:0,id:item.id,level:item.level,firstAnswer:null,attempts:0,answers:[],wordCorrect:null,firstReason:null,reasonAttempts:0,reason:null,reasonCorrect:null,hints:0,powers:[],shownExample:false,complete:false,accuracy:null,review:null,sentence:'',mode:'',startedAt:new Date().toISOString(),skill:item.skill,prompt:item.prompt,target:item.answer};}
function openQuestion(item,practice=false){
 if(!session)return;stopAudio();qstate={item,practice,record:practice?blankRecord(item):null,step:'word',feedback:null,hint:false,radio:false,two:false,double:false,composeMode:'cards',tokens:[],draft:'',selectedAction:item.action};
 if(!practice){session.records[item.id]??=blankRecord(item);const r=recordFor();qstate.step=r.wordCorrect&&item.type==='reason'?'reason':'word';qstate.draft=r.draft||'';qstate.tokens=r.tokens||[];qstate.composeMode=r.composeMode||'cards';qstate.selectedAction=r.selectedAction||item.action;qstate.two=r.powers.includes('two');qstate.double=r.powers.includes('double');}
 qstate.activity=recordFor().activity||newActivity(item);recordFor().activity=qstate.activity;if(session.mode==='guidance'){qstate.hint=true;if(!recordFor().guidanceApplied){recordFor().hints++;recordFor().guidanceApplied=true;applyActivityHint(item,qstate.activity);}}renderQuestion();speak([item.prompt,...(qstate.hint?[item.hint]:[])]);save();
}
function renderLegacyQuestion(){const q=qstate,i=q.item,r=recordFor(),done=q.feedback==='correct'||q.feedback==='submitted';const reason=q.step==='reason';let choices=reason?i.reasonChoices:[...i.choices];if((session.mode==='guidance'||q.two)&&choices.length>2){const correct=choices.indexOf(reason?i.reason:i.answer);choices=choices.filter((_,k)=>k===correct||k===choices.findIndex((_,j)=>j!==correct));}
 const prompt=reason?'Mengapa kamu memilih perkataan itu?':i.prompt;let task='';
 if(i.type==='compose'&&!done){task=composeView();}
 else if(!done){task=`${reason?`<div class="notice success">✓ Kata pilihan: <strong>${e(i.answer)}</strong></div>`:''}<div class="choice-list">${choices.map((c,k)=>`<div class="choice-row">${btn(reason?'reason-answer':'answer',`<span class="letter">${'ABC'[k]}</span>${e(c)}`,'answer',`data-answer="${e(c)}"`)}${audioBtn(c)}</div>`).join('')}</div>${reason?btn('oral-reason','Saya beri alasan secara lisan','outline small','style="margin-top:15px"'):''}`;}
 const wrong=q.feedback==='wrong';let feedback=done?`<div class="feedback correct" role="status"><strong><span class="confetti-star" style="color:#c48e00">${icon('star')}</span>${q.feedback==='submitted'?'Usaha yang baik!':r.attempts>1||r.hints?'Bagus! Kamu berjaya!':'Betul! Bagus!'}</strong><p>${q.feedback==='submitted'?'Jawapan disimpan untuk semakan guru. Laluan kini dibuka.':e(i.explanation)}</p><p class="subtle">Cabaran ${i.index} selesai. Kamu berada di Peringkat ${i.level}.</p>${audioBtn(q.feedback==='submitted'?audioScripts().savedAnswer:i.explanation)} ${btn('question-next',q.practice?'Selesai ulang kaji':'Teruskan misi '+icon('arrow'),'primary')}</div>`:wrong?`<div class="feedback wrong" role="status"><strong>${icon('close')}Belum tepat. Mari cuba lagi.</strong><p>${e(reason?'Fikirkan tujuan tindakan anggota polis.':i.hint)}</p></div>`:'';
 const images=i.type==='compose'&&i.index===4?`<div class="compose-images">${img('reading')}${img('helping')}</div>`:img(q.selectedAction,`question-image ${q.radio?'highlight':''}`);
 const shortPrompt=done?(q.feedback==='submitted'?'Laporan kamu sudah diterima.':'Laluan kamu sudah terbuka!'):prompt;
 showModal('question',`<div class="dialog-head"><span class="pill">${e(i.id)} · ${e(LEVELS[i.level-1].name)}${q.practice?' · Ulang kaji':''}</span>${btn('pause',icon('pause'),'icon-btn','aria-label="Jeda cabaran"')}</div><div class="question-layout"><div>${images}${i.level===2&&done?`<p class="word-parts" style="margin:14px 0 0">${wordParts(i.answer,words().find(w=>w.word===i.answer)?.prefix||'mem-')}</p><p class="help center">Awalan berwarna biru. Baki kata berwarna perang.</p>`:''}</div><div><div class="btn-row" style="justify-content:space-between;align-items:flex-start"><p class="question-text" style="flex:1">${e(shortPrompt)}</p>${audioBtn(prompt)}</div>${task}${feedback}${!done&&q.hint?`<div class="hint-box">${icon('search')} ${e(i.hint)} ${audioBtn(i.hint)}</div>`:''}${!done&&r.shownExample?`<div class="notice">Contoh untuk dibincangkan: ${e(i.explanation)} ${audioBtn(i.explanation)}</div>`:''}</div></div>${!done?`<div class="quiz-powers">${['hint','radio','two','double'].map(powerButton).join('')}</div><div class="btn-row" style="margin-top:12px">${btn('example','Lihat contoh bersama guru','small outline')}<span class="subtle">Bantuan direkod. Tiada penalti masa.</span></div>`:''}`,true);
}
function composeView(){const q=qstate,i=q.item,r=recordFor();return `${i.index===3?`<div class="compose-images">${['searching','traffic'].map(a=>btn('select-picture',img(a,''),q.selectedAction===a?'selected':'',`data-picture="${a}" aria-label="Pilih gambar ${a==='searching'?'mencari':'mengawal'}"`)).join('')}</div>`:''}<div class="form-tabs">${[['cards','Susun kad'],['typing','Taip ayat'],['oral','Jawab lisan']].map(([v,t])=>btn('compose-mode',t,q.composeMode===v?'active':'',`data-mode="${v}"`)).join('')}</div>${q.composeMode==='cards'?`<div class="sentence-tray"><div class="word-cards">${q.tokens.length?q.tokens.map((k,j)=>btn('remove-token',e(i.cards[k]),'',`data-token="${j}" aria-label="Keluarkan ${e(i.cards[k])}"`)).join(''):'<p>Tekan kad di bawah mengikut susunan ayat.</p>'}</div></div><div class="word-cards">${i.cards.map((t,k)=>btn('add-token',e(t),'',`data-token="${k}" ${q.tokens.includes(k)?'disabled':''}`)).join('')}</div>`:q.composeMode==='typing'?`<label for="sentence-input">Ayat kamu</label><textarea id="sentence-input" maxlength="1200" rows="4" placeholder="Anggota polis…">${e(q.draft)}</textarea>`:`<div class="notice">Sebut ayat kepada guru. Guru boleh mencatat jawapan kamu di bawah. Tiada suara murid dirakam.</div><label for="sentence-input">Catatan jawapan lisan (boleh diisi guru kemudian)</label><textarea id="sentence-input" maxlength="1200" rows="3">${e(q.draft)}</textarea>`}<div class="btn-row" style="margin-top:16px">${btn('submit-compose','Hantar laporan '+icon('arrow'),'primary')}</div><p class="help">Guru menyemak imbuhan, makna, ayat dan bantuan. Lebih daripada satu ayat boleh diterima.</p>`;}
function answer(value,isReason=false){if(!qstate||modal!=='question'||['correct','submitted'].includes(qstate.feedback))return;const i=qstate.item,r=recordFor();if(isReason){r.reasonAttempts++;r.firstReason??=value;r.reason=value;r.reasonCorrect=value===i.reason;if(!r.reasonCorrect){qstate.feedback='wrong';r.hints++;chime(false);renderQuestion();speak(audioScripts().wrong);save();return;}completeQuestion(false);return;}
 r.attempts++;r.firstAnswer??=value;r.answers.push(value);r.wordCorrect=(i.accepted||[i.answer]).includes(value);if(!r.wordCorrect){r.hints++;qstate.hint=true;qstate.feedback='wrong';chime(false);renderQuestion();speak([audioScripts().wrong,i.hint]);save();return;}r.wordEvidence=assessEvidence(r.attempts,r.hints,r.shownExample);if(i.type==='reason'){qstate.step='reason';qstate.feedback=null;chime(true);renderQuestion();speak([audioScripts().correct,i.reason?'Mengapa kamu memilih perkataan itu?':i.explanation]);save();}else completeQuestion(false);}
function completeQuestion(open=false){
 const i=qstate.item,r=recordFor();if(r.complete)return;
 r.complete=true;r.completedAt=new Date().toISOString();r.accuracy=open?null:true;r.evidence=open?'Menunggu semakan guru':assessEvidence(r.attempts,r.hints,r.shownExample);
 r.gameStars=qstate.practice?0:qstate.double?2:1;
 if(qstate.practice)session.practice.push({...r,practiceAt:r.completedAt});else{session.stars+=r.gameStars;session.cycleCount++;session.powers.hint++;session.powers.radio++;if(session.cycleCount%2===0)session.powers.two++;syncMissionProgress(session);}
 qstate.feedback=open?'submitted':'correct';chime(true);renderQuestion();save();speak([r.attempts>1||r.hints?audioScripts().guidedSuccess:audioScripts().correct,i.explanation]);
}
function usePower(id){if(!session||!session.assist.includes(id)||session.powers[id]<=0)return;const inQuiz=modal==='question';if(id!=='path'&&!inQuiz){notify('Kuasa ini digunakan semasa cabaran.');return;}if(inQuiz&&['correct','submitted'].includes(qstate.feedback))return;if(inQuiz&&recordFor().powers.includes(id)){notify('Kuasa ini sudah digunakan untuk cabaran ini.');return;}
 session.powers[id]--;session.powerLog.push({power:id,item:inQuiz?qstate.item.id:null,at:new Date().toISOString()});if(id==='path'){pathOn=true;drawMaze();speak(audioScripts().route);render();}
 else{const r=recordFor();r.powers.push(id);if(id==='hint'||id==='radio'||id==='two'&&qstate.item.choices.length<=2){qstate.hint=true;r.hints++;}if(id==='radio')qstate.radio=true;if(id==='two'){qstate.two=true;r.hints++;}if(id==='double')qstate.double=true;if(['hint','radio','two'].includes(id)&&qstate.item.gameType)applyActivityHint(qstate.item,qstate.activity);renderQuestion();speak(id==='radio'?[audioScripts().radio,qstate.item.hint]:id==='double'?audioScripts().doubleStars:qstate.item.hint);}save();}
function questionNext(){const practice=qstate.practice;closeModal();qstate=null;if(practice){render();return;}render();if(stationComplete(session,session.level)){finishLevel();return;}if(session.cycleCount>=session.limit){showModal('break',`${dialogHead('Misi hari ini tercapai!',false)}<p>Kamu menyelesaikan ${session.cycleCount} cabaran. Mari berehat atau sambung aktiviti maujud.</p><div class="btn-row">${btn('continue-session','Teruskan menjelajah','primary')}${btn('map','Ke peta','outline')}${btn('print','Bahan maujud','outline')}</div>`);}}
function finishLevel(){
 if(!stationComplete(session,session.level))return;
 syncMissionProgress(session);session.levelRewards??=[];if(!session.levelRewards.includes(session.level)){session.levelRewards.push(session.level);session.powers.double++;session.powers.path+=2;}save();
 const l=LEVELS[session.level-1];showModal('level-summary', `<div class="center"><img class="award" src="assets/favicon.svg" alt="Lencana stesen"><span class="pill gold">Stesen ${l.id} selesai · ${e(l.subtitle)}</span><h2>Tahniah, ${e(session.name)}!</h2><p>Empat cabaran selesai. Kamu memperoleh lencana dan satu digit kod.</p><div class="code-card" style="max-width:200px;margin:18px auto"><small>Stesen ${l.id}</small><strong>${session.earnedCodes[l.id-1]}</strong><small>Digit disimpan dalam Kad Kod Saya</small></div><p>Masa aktif: ${clockText(session.levelMs[l.id]||0)}</p><div class="btn-row" style="justify-content:center">${allStationsComplete(session)?btn('final','Ke Pusat Kawalan · Buka Peti','gold'):btn('map','Ke stesen seterusnya','primary')}${btn('codes','Kad Kod Saya','outline')}${allStationsComplete(session)?btn('map','Peta misi','outline'):''}</div></div>`);chime(true);speak(audioScripts().stageSummaries?.[l.id-1]);
}
function showTutorial(){tutorialX=0;renderTutorial();speak(audioScripts().tutorial);}
function renderTutorial(){showModal('tutorial',`${dialogHead('Misi latihan: gerak dan kenali kata')}<p>Tekan anak panah kanan dua kali untuk sampai ke petunjuk.</p><div class="tutorial-track" style="display:grid;grid-template-columns:repeat(3,1fr);border:8px solid #b8d6bd;background:#fff5df;border-radius:18px;overflow:hidden">${[0,1,2].map(x=>`<div style="height:110px;border-right:2px dashed #b2b9b2;display:flex;align-items:center;justify-content:center">${tutorialX===x?'<img src="assets/v2/police-boy.png" alt="Anggota polis" style="height:100px;width:100px">':x===2?'<img src="assets/v2/action-reading.png" alt="Petunjuk membaca" style="height:90px;width:110px">':''}</div>`).join('')}</div><div class="btn-row" style="justify-content:center;margin:20px 0"><button data-dir="left" aria-label="Latihan gerak kiri">←</button><button data-dir="right" aria-label="Latihan gerak kanan">→</button></div>${tutorialX===2?`<div class="notice"><strong>Kamu sampai ke petunjuk!</strong><p>Polis sedang membaca. Pilih kata berimbuhan awalan.</p><div class="btn-row">${btn('tutorial-wrong','baca','outline')}${btn('tutorial-correct','membaca','primary')}</div></div>`:'<p class="help center">Dinding menghalang laluan. Kamu tidak kehilangan nyawa.</p>'}<div class="tutorial-steps"><div class="tutorial-step"><span class="number">1</span><div><strong>Jelajah laluan</strong><small>Gunakan pad arah, anak panah atau WASD.</small></div></div><div class="tutorial-step"><span class="number">2</span><div><strong>Jawab dan buka pintu</strong><small>Jika belum tepat, cuba lagi dengan petunjuk.</small></div></div><div class="tutorial-step"><span class="number">3</span><div><strong>Kumpul lencana</strong><small>Selesaikan empat cabaran dan pergi ke tamat.</small></div></div></div>`);}
function tutorialMove(dir){if(dir==='right')tutorialX=Math.min(2,tutorialX+1);if(dir==='left')tutorialX=Math.max(0,tutorialX-1);renderTutorial();}
function controlsDialog(){showModal('controls',`${dialogHead('Pilih kawalan kamu')}<p>Kemajuan kamu dikekalkan apabila menukar kawalan.</p><div class="tutorial-steps">${[['mouse','Tetikus / sentuhan'],['keyboard','Papan kekunci'],['hand','Gerakan tangan melalui kamera']].map(([v,t])=>btn('control-select',t,session?.control===v?'primary':'outline',`data-control="${v}"`)).join('')}</div><label for="hand-sensitivity">Sensitiviti kanta</label><input id="hand-sensitivity" type="range" min=".7" max="2" step=".1" value="${data.settings.sensitivity}" style="width:100%"><p class="help">Tuding dan tahan 1.25 saat. Kamera diproses pada peranti; video tidak dirakam atau dimuat naik.</p>`);}
async function activateHands(){try{const started=await startHands({sensitivity:data.settings.sensitivity,onMove:move,onStatus:tracked=>{const n=$('#hand-notice');if(n)n.hidden=tracked||session?.control!=='hand';},onError:()=>{notify('Penjejakan terhenti. Gunakan tetikus untuk meneruskan.');}});if(started)notify('Letakkan jari di tengah skrin, kemudian tekan Kalibrasi pada panel kamera.');}catch(err){showModal('camera-error',`${dialogHead('Kamera belum tersedia',false)}<p>${e(err.message)}</p><div class="btn-row">${btn('camera-retry','Cuba Lagi','primary')}${btn('mouse','Guna Tetikus','outline')}</div>${err.detail?`<details class="help"><summary>Butiran teknikal</summary><p>${e(err.detail)}</p></details>`:''}`);}}
function overallView(){if(!session)return '<p>Mulakan sesi untuk melihat pencapaian.</p>';const rs=Object.values(session.records).filter(r=>r.complete),first=rs.filter(r=>r.evidence==='Percubaan pertama'),practice=[...new Set(rs.filter(r=>r.attempts>1).map(r=>itemBy(r.id)?.answer))];return `<div class="narrow center"><img class="award" src="assets/favicon.svg" alt="Lencana OPS ImAn"><h1 style="font-size:42px">Setiap usaha ialah kemajuan.</h1><p>${e(session.name)}, kamu menyelesaikan ${rs.length} cabaran dan mengumpulkan ${session.completedLevels.length} lencana bahasa.</p><div class="summary-stats"><div><strong>${session.stars}</strong><small>bintang permainan</small></div><div><strong>${first.length}</strong><small>betul kali pertama</small></div><div><strong>${clockText(session.activeMs)}</strong><small>masa aktif</small></div></div><div class="notice">${practice.length?`Mari berlatih ${practice.map(w=>'“'+e(w)+'”').join(', ')} lagi!`:'Teruskan berlatih dan gunakan kata berimbuhan dalam ayat.'}</div><p class="help">Bintang menghargai usaha. TP ditentukan oleh guru berdasarkan bukti pembelajaran.</p><div class="btn-row" style="justify-content:center">${btn('map','Sambung pengembaraan','primary')}${btn('review','Misi ulang kaji','outline')}${certificateEligible(session)?btn('certificate-view','Lihat Sijil','outline',`data-id="${session.id}"`):''}${btn('csv','Eksport rekod','outline')}</div></div>`;}
function badgesDialog(){showModal('badges',`${dialogHead('Buku koleksi lencana bahasa')}<div class="map-grid">${LEVELS.map(l=>`<div class="card center" style="padding:15px;${session.completedLevels.includes(l.id)?'':'filter:grayscale(1);opacity:.65'}"><img src="assets/favicon.svg" style="width:60px;height:70px" alt="Lencana ${l.id}"><h3 style="font-size:20px">${e(l.name)}</h3><small>${session.completedLevels.includes(l.id)?'✓ Dikumpul':'Belum dikumpul'}</small></div>`).join('')}</div>`,true);}
let mazeCamera=matchMedia('(max-width:760px)').matches;
let certificateSessionId=null,certificateMuted=false,certificateBusy=false;
const certificateSession=()=>data.sessions.find(s=>s.id===certificateSessionId)||session;
function certificateData(s){return ensureCertificate(s,data.settings);}
function certificateCelebration(){const stars=$('.certificate-stars');if(stars)setTimeout(()=>stars.remove(),2900);if(!certificateMuted){chime(true);speak(CERTIFICATE_VOICE,{force:true});}}
function showCompletion(s){
 certificateSessionId=s.id;const details=certificateData(s);certificateMuted=details.silent??s.audio===false;
 showModal('completion',`${starShower(data.settings.reduced||matchMedia('(prefers-reduced-motion: reduce)').matches)}<div class="center"><img class="completion-cast" src="assets/v2/pose-celebrate.png" alt="Pasukan polis meraikan kejayaan kamu"><div class="success-chest open" aria-label="Peti Kejayaan terbuka">★</div>${codeCards(s,true)}<span class="pill gold">6 misi · 24 cabaran selesai</span><h2 class="completion-title">Tahniah, ${e(s.name)}! Kamu berjaya menyelesaikan misi OPS ImAn!</h2><p>Sijil ini menghargai usaha kamu. Kejayaan dengan bantuan tetap diraikan.</p><div class="certificate-actions btn-row">${btn('certificate-view','Lihat Sijil','primary',`data-id="${s.id}"`)}${btn('certificate-download',icon('download')+' Muat Turun PDF','outline')}${btn('certificate-print',icon('print')+' Cetak Sijil','outline')}${btn('home','Kembali ke Menu Utama','outline')}</div><div class="certificate-sound btn-row">${btn('certificate-voice',icon('sound')+' Ulang suara','small outline',certificateMuted?'disabled':'')}<label class="check-row"><input id="certificate-mute" type="checkbox" ${certificateMuted?'checked':''}> Senyap</label></div></div>`);
 certificateCelebration();save();
}
function showCertificate(s=certificateSession(),celebrate=true){
 if(!certificateEligible(s)){notify('Selesaikan enam stesen dan buka Peti Kejayaan untuk mendapatkan sijil.');return;}
 certificateSessionId=s.id;const details=certificateData(s);certificateMuted=details.silent??s.audio===false;stopAudio();
 showModal('certificate',`${celebrate?starShower(data.settings.reduced||matchMedia('(prefers-reduced-motion: reduce)').matches):''}${dialogHead('Sijil Wira Imbuhan Awalan')}<div class="certificate-preview" id="certificate-preview">${certificateSVG(details,{ink:details.ink})}</div><div class="certificate-actions btn-row">${btn('certificate-download',icon('download')+' Muat Turun PDF','primary')}${btn('certificate-print',icon('print')+' Cetak Sijil','outline')}${btn('home','Kembali ke Menu Utama','outline')}</div><div class="certificate-options"><label class="check-row"><input id="certificate-ink" type="checkbox" ${details.ink?'checked':''}> Versi jimat dakwat</label><label class="check-row"><input id="certificate-mute" type="checkbox" ${certificateMuted?'checked':''}> Senyap</label>${btn('certificate-voice',icon('sound')+' Ulang suara','small outline',certificateMuted?'disabled':'')}</div><details class="certificate-editor"><summary>Semak nama dan pengesahan guru sebelum mencetak</summary><form id="certificate-form" data-id="${s.id}"><div class="form-grid">${field('Nama pada sijil','certificate-name',details.displayName,'text','required maxlength="160"')}${field('Kelas','certificate-class',details.className,'text','required maxlength="60"')}${field('Nama guru','certificate-teacher',details.teacherName||'','text','maxlength="120"')}${field('Nama sekolah (pilihan)','certificate-school',details.schoolName||'','text','maxlength="120"')}</div><p class="help">Tarikh selesai: ${e(formattedCompletionDate(details.completedAt))}. Tarikh ini diambil daripada rekod penyelesaian. Pembetulan nama disimpan pada sijil sesi ini.</p><button class="primary small" type="submit">Simpan pembetulan & pratonton</button></form></details><p class="help certificate-download-status" role="status"></p>`,true);
 $('.dialog').classList.add('certificate-dialog');document.fonts.ready.then(()=>{if(modal==='certificate'&&certificateSessionId===s.id)$('#certificate-preview').innerHTML=certificateSVG(certificateData(s),{ink:s.certificate.ink});});save();if(celebrate)certificateCelebration();
}
function saveCertificateForm(){const form=$('#certificate-form'),s=certificateSession();if(!certificateEligible(s))throw Error('Sijil belum tersedia.');if(form){if(!form.reportValidity())return false;const f=new FormData(form);if(!String(f.get('certificate-name')).trim()||!String(f.get('certificate-class')).trim())throw Error('Nama dan kelas tidak boleh kosong.');Object.assign(s.certificate,{displayName:String(f.get('certificate-name')).trim(),className:String(f.get('certificate-class')).trim(),teacherName:String(f.get('certificate-teacher')).trim(),schoolName:String(f.get('certificate-school')).trim()});}save();return certificateData(s);}
async function exportCertificatePDF(){
 if(certificateBusy)return;const details=saveCertificateForm();if(!details)return;certificateBusy=true;const controls=$$('[data-action=certificate-download]');controls.forEach(b=>b.disabled=true);const status=$('.certificate-download-status');if(status)status.textContent='Sedang menjana PDF sijil…';
 try{await downloadCertificate(details,{ink:details.ink});if(status)status.textContent='PDF sijil berjaya dijana.';notify('PDF sijil telah dijana.');}finally{certificateBusy=false;controls.forEach(b=>b.disabled=false);}
}
function field(label,name,value,type='text',extra=''){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${e(value)}" ${extra}></div>`;}
function area(label,name,value,extra=''){return `<div class="field"><label for="${name}">${label}</label><textarea id="${name}" name="${name}" ${extra}>${e(value)}</textarea></div>`;}
function selectField(label,name,values,value){return `<div class="field"><label for="${name}">${label}</label><select id="${name}" name="${name}">${values.map(v=>{const [k,t]=Array.isArray(v)?v:[v,v];return `<option value="${e(k)}" ${String(value)===String(k)?'selected':''}>${e(t)}</option>`;}).join('')}</select></div>`;}
function teacherView(){return `<span class="eyebrow">Ruang guru · data peranti ini sahaja</span><div class="section-title"><div><h1 style="font-size:40px;margin:12px 0">Bimbing setiap langkah.</h1><p>Markah permainan, bukti bahasa dan pertimbangan TP direkod secara berasingan.</p></div>${btn('map','Kembali bermain','outline small')}</div><div class="admin-tabs">${[['records','Rekod & pentaksiran'],['settings','Tetapan sesi'],['content','Bank kandungan'],['audio','Rakaman audio']].map(([k,t])=>btn('teacher-tab',t,teacherTab===k?'active':'',`data-tab="${k}"`)).join('')}</div>${({records:recordsView,settings:settingsView,content:contentView,audio:audioView}[teacherTab])()}`;}
function recordsView(){const selected=data.sessions.find(s=>s.id===selectedRecord);return `<div class="card"><div class="btn-row">${btn('csv',icon('download')+' Eksport CSV','primary small')}${btn('backup','Sandaran JSON','outline small')}${btn('restore','Pulihkan sandaran','outline small')}<input type="file" id="restore-file" accept="application/json" hidden></div><p class="help">Simpanan pelayar boleh hilang jika data pelayar dipadam. Eksport salinan secara berkala. Tiada data murid dihantar ke pelayan.</p>${data.sessions.length?`<div class="table-wrap"><table><thead><tr><th>Nama / kelas</th><th>Tarikh</th><th>Cabaran</th><th>Bintang</th><th>Masa aktif</th><th>TP guru</th><th>Tindakan</th></tr></thead><tbody>${[...data.sessions].reverse().map(s=>`<tr><td><b>${e(s.name)}</b><br>${e(s.className)}</td><td>${dateText(s.createdAt)}</td><td>${Object.values(s.records).filter(r=>r.complete).length}/24</td><td>${s.stars}</td><td>${clockText(s.activeMs)}</td><td>${s.teacher?.tp?'TP'+s.teacher.tp:'Belum ditentukan'}</td><td>${btn('record','Semak','small',`data-id="${s.id}"`)} ${btn('resume-record','Sambung','small',`data-id="${s.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="notice">Belum ada rekod murid. Mulakan pengembaraan untuk mengumpul bukti.</div>'}</div>${selected?recordDetail(selected):''}`;}
function dateText(iso){return iso?new Intl.DateTimeFormat('ms-MY',{timeZone:'Asia/Kuala_Lumpur',dateStyle:'medium'}).format(new Date(iso)):'—';}
function recordDetail(s){const rs=Object.values(s.records),completed=rs.filter(r=>r.complete);return `<div class="card record-detail"><div class="section-title"><div><h2>${e(s.name)} · ${e(s.className)}</h2><p>${dateText(s.createdAt)} · ${s.completedLevels.length} peringkat selesai · ${completed.length} cabaran selesai</p></div><div class="btn-row">${certificateEligible(s)?btn('certificate-view','Lihat Sijil','primary small',`data-id="${s.id}"`):''}${btn('print-report','Cetak laporan','outline small',`data-id="${s.id}"`)}${btn('delete-session','Padam sesi','danger small',`data-id="${s.id}"`)}</div></div><div class="notice">TP ialah pertimbangan profesional guru berdasarkan Standard Prestasi. Peringkat 1–6, bintang dan kelajuan bukan TP.</div><form id="assessment-form" data-id="${s.id}"><div class="form-grid">${selectField('Tahap Penguasaan (manual)','tp',[['','Belum ditentukan'],...[1,2,3,4,5,6].map(n=>[n,`TP${n}`])],s.teacher?.tp)}${field('Tarikh pentaksiran','assessment-date',s.teacher?.date||'','date')}</div>${area('Ulasan dan bukti pertimbangan guru','teacher-notes',s.teacher?.notes||'')}<button class="primary small" type="submit">Simpan pertimbangan guru</button></form><h3>Kod dan misi akhir</h3>${codeCards(s,true)}<p>Status Peti Kejayaan: ${s.finalMission?.complete?'Dibuka':allStationsComplete(s)?'Sedia dibuka':'Menunggu enam stesen'} · Sijil: ${certificateEligible(s)?'Tersedia':'Belum tersedia'}</p><h3 style="margin-top:26px">Bukti setiap cabaran</h3><div class="table-wrap"><table><thead><tr><th>Kod / Aktiviti / Masa</th><th>Jawapan pertama</th><th>Percubaan</th><th>Bukti perkataan</th><th>Alasan (berasingan)</th><th>Bantuan</th><th>Status</th></tr></thead><tbody>${rs.map(r=>`<tr><td>${r.id}<br>${e(r.gameType==='legacy'?'Rekod terdahulu':GAME_NAMES[GAME_TYPES.indexOf(r.gameType)]||r.gameType||'')}<br>${clockText(r.activeMs||0)}</td><td>${e(r.firstAnswer??'—')}</td><td>${r.attempts}</td><td>${e(r.wordEvidence||r.evidence||'Belum selesai')}</td><td>${r.reason?`${e(r.reason)}<br>Pertama: ${e(r.firstReason||'Lisan')}<br>${r.reasonAttempts} percubaan · ${r.reasonCorrect===null?'Menunggu guru':r.reasonCorrect?'Betul':'Belum tepat'}`:'—'}</td><td>${r.hints} petunjuk<br>${r.powers.map(p=>e(POWER[p]?.name||p)).join(', ')}${r.shownExample?'<br>Contoh ditunjukkan':''}</td><td>${r.complete?'Selesai':'Dalam proses'}<br>${r.accuracy===null?'Semakan guru':r.accuracy?'Tepat':''}</td></tr>`).join('')}</tbody></table></div><h3 style="margin-top:25px">Ayat dan alasan lisan untuk disemak</h3>${rs.filter(r=>r.mode||r.reasonMode==='oral').map(r=>`<details class="record-detail" open><summary>${r.id} · ${e(r.mode||'Alasan lisan')}</summary><form class="review-form" data-session="${s.id}" data-item="${r.id}">${area('Jawapan murid / transkripsi guru','response',r.sentence||r.reason||'')}<div class="rubric-grid">${['Imbuhan sesuai','Makna sesuai','Ayat lengkap'].map((label,k)=>selectField(label,'rubric-'+k,[['','Belum dinilai'],['yes','Ya'],['developing','Sedang berkembang'],['no','Perlu bimbingan']],r.review?.criteria?.[k]||'')).join('')}${selectField('Tahap bantuan','support',['Belum dinilai','Tanpa bantuan','Petunjuk','Contoh','Bimbingan penuh'],r.review?.support||'Belum dinilai')}${selectField('Keputusan semakan','review-status',[['pending','Belum disemak'],['accepted','Diterima'],['revise','Perlu latihan lagi']],r.review?.status||'pending')}</div>${area('Ulasan rubrik','review-notes',r.review?.notes||'')}<button class="primary small" type="submit">Simpan semakan ${r.id}</button></form></details>`).join('')||'<p class="help">Tiada jawapan terbuka dalam sesi ini.</p>'}<h3>Masa setiap peringkat</h3><p>${LEVELS.map(l=>`P${l.id}: ${clockText(s.levelMs[l.id]||0)}`).join(' · ')}</p><h3>Ulang kaji</h3><p>${s.practice?.length||0} cabaran ulang kaji direkod secara berasingan.</p></div>`;}
function settingsView(){const s=data.settings;return `<form id="settings-form"><div class="admin-grid"><section class="card"><h3>Pembelajaran</h3>${selectField('Mod lalai','mode',[['guidance','Bimbingan — dua pilihan dan audio automatik'],['standard','Standard — bantuan atas permintaan'],['enrichment','Pengayaan — bermula pada analisis dan ciptaan']],s.mode)}${selectField('Peringkat permulaan','startLevel',LEVELS.map(l=>[l.id,`${l.id}. ${l.name}`]),s.startLevel)}${selectField('Jumlah cabaran sebelum rehat','limit',[1,2,4,8,12,24],s.limit)}<div class="field"><label>Perkataan sasaran untuk ulang kaji dan latihan</label>${words().map(w=>`<label class="check-row"><input type="checkbox" name="targets" value="${e(w.word)}" ${s.targets.includes(w.word)?'checked':''}> ${e(w.base)} → ${e(w.word)}</label>`).join('')}<small>24 cabaran teras dikekalkan. Sasaran pilihan digunakan dalam misi latihan guru.</small></div><div class="field"><label>Pengayaan tambahan (pilihan)</label>${['ber-','di-','ter-'].map(g=>`<label class="check-row"><input type="checkbox" name="enrichment" value="${g}" ${s.enrichment.includes(g)?'checked':''}> ${g}</label>`).join('')}</div></section><section class="card"><h3>Akses dan bantuan</h3>${selectField('Saiz teks murid','font',[24,28,32],s.font)}${selectField('Kelajuan bacaan','rate',[[.7,'Perlahan'],[.9,'Sederhana'],[1.05,'Biasa']],s.rate)}<div class="field"><label class="check-row"><input type="checkbox" name="easy" ${s.easy?'checked':''}> Maze mudah pada semua peringkat</label><label class="check-row"><input type="checkbox" name="reduced" ${s.reduced?'checked':''}> Kurangkan animasi</label></div><div class="field"><label>Jenis bantuan tersedia</label>${Object.entries(POWER).map(([k,p])=>`<label class="check-row"><input type="checkbox" name="assist" value="${k}" ${s.assist.includes(k)?'checked':''}> ${p.name}</label>`).join('')}</div><div class="field"><label class="check-row"><input type="checkbox" name="music" ${s.music?'checked':''}> Muzik latar lembut</label><label for="volume">Kelantangan audio</label><input id="volume" name="volume" type="range" min="0" max="1" step=".05" value="${s.volume}" style="width:100%"></div><div class="notice">Tiada had masa wajib. Masa navigasi tidak digunakan untuk menentukan keupayaan tatabahasa.</div></section><section class="card" style="grid-column:1/-1"><h3>Nama guru dan sekolah pada sijil</h3><div class="form-grid">${field('Nama guru','teacherName',s.teacherName||'','text','maxlength="120"')}${field('Nama sekolah (pilihan)','schoolName',s.schoolName||'','text','maxlength="120"')}</div><p class="help">Digunakan apabila sijil baharu dijana. Sijil terdahulu boleh dibetulkan melalui Rekod & pentaksiran → Semak → Lihat Sijil.</p><h3>Kurikulum boleh sunting</h3>${area('Standard Kandungan','sk',s.curriculum.sk)}${area('Standard Pembelajaran','sp',s.curriculum.sp)}${field('Dokumen DSKP yang digunakan','document',s.curriculum.document)}<label class="check-row"><input type="checkbox" name="curriculum-confirmed" ${s.curriculum.confirmed?'checked':''}> Guru telah menyemak padanan dengan dokumen yang digunakan</label><p class="help">Label dibekalkan: 5.2.1(iii), kata berimbuhan awalan. Rujukan perbandingan: <a href="https://bukuteksdigital.my/wp-content/uploads/2020/06/DSKP-KSSR-SEMAKAN-2017-BAHASA-MELAYU-TAHUN-2.pdf" target="_blank" rel="noopener">dokumen KPM Bahasa Melayu SK Tahun 2, terbitan 2016, halaman 40</a>. Guru mengesahkan dokumen sekolah.</p></section></div><div class="btn-row" style="margin-top:24px"><button class="primary" type="submit">Simpan tetapan</button>${btn('target-practice','Latihan perkataan sasaran','outline','type="button"')}</div><p class="help">Mod, peringkat awal dan bentuk maze digunakan untuk sesi baharu. Teks, audio dan bantuan boleh diselaraskan pada sesi semasa.</p></form>`;}
function contentView(){const i=itemBy(editItem),w=words().find(w=>w.base===editWord)||words()[0];return `<div class="notice">Suntingan disimpan pada peranti ini. Semak imbuhan, gambar dan konteks. Pratonton cetakan mengikut suntingan; PDF asal dikekalkan.</div><div class="admin-grid"><section class="card"><h3>Bank 24 cabaran</h3>${selectField('Pilih kod cabaran','item-select',ITEMS.map(i=>[i.id,`${i.id} · ${LEVELS[i.level-1].name}`]),editItem)}<form id="content-form" data-id="${i.id}">${area('Soalan','prompt',i.prompt,'required')}${selectField('Ilustrasi tindakan','action',['reading','helping','searching','traffic','writing','taking','sweeping','walking','fallen'],i.action)}${area('Pilihan, satu bagi setiap baris (2–3 untuk soalan tertutup)','choices',i.choices.join('\n'))}${field('Jawapan diterima (pisahkan dengan | jika lebih daripada satu)','answer',i.answer,'text','required')}${area('Penjelasan / contoh jawapan','explanation',i.explanation,'required')}${area('Petunjuk','hint',i.hint,'required')}${i.type==='reason'?area('Alasan betul','reason',i.reason)+area('Pilihan alasan, satu setiap baris','reasonChoices',i.reasonChoices.join('\n')):''}${i.type==='sentence'?area('Kad perkataan, satu setiap baris','cards',i.cards.join('\n')):''}<p class="help">Kemahiran: ${e(i.skill)} · Jenis: ${e(i.type)}. Audio baharu boleh ditambah di tab Rakaman audio.</p><div class="btn-row"><button type="submit" class="primary small">Simpan cabaran</button>${btn('reset-item','Pulihkan asal','outline small','type="button"')}</div></form></section><section class="card"><h3>Bank kata dasar dan awalan</h3>${selectField('Pilih kata asal','word-select',WORD_BANK.map(w=>[w.base,w.base]),editWord)}<form id="word-form" data-base="${w.base}">${field('Perkataan lengkap','word',w.word,'text','required')}${selectField('Bentuk awalan','prefix',['me-','mem-','men-','meng-','meny-'],w.prefix)}${selectField('Gambar','word-action',['reading','helping','searching','traffic','writing','taking','sweeping','walking','fallen'],w.action)}${area('Nota pembentukan / perubahan huruf','note',w.note,'required')}<button type="submit" class="primary small">Simpan perkataan</button></form><div class="notice">Contoh perubahan: tulis → menulis, sapu → menyapu, kawal → mengawal. Gunakan perkataan lengkap yang betul; jangan cantum huruf secara mekanikal.</div><div class="btn-row">${btn('export-content','Eksport bank JSON','outline small')}${btn('library','Pratonton buku kata','outline small')}</div></section></div>`;}
function audioTexts(){return [...new Set([INTRO,CERTIFICATE_VOICE,...Object.values(audioScripts()).flat().filter(t=>typeof t==='string'),FINAL_INSTRUCTION,FINAL_SUCCESS,FINAL_RETRY,...ACTIVITY_INSTRUCTIONS,...currentItems().flatMap(i=>[i.prompt,...i.choices,i.hint,i.explanation,...(i.cards||[]),...(i.pieces||[]),...(i.reasonChoices||[])]),...words().flatMap(w=>[w.word,w.note])])];}
function audioView(){return `<div class="card"><h3>Audio Melayu dan rakaman guru</h3><div class="notice">${e(voiceStatus())}</div><p>Klip sintesis Bahasa Melayu disertakan untuk arahan, soalan dan pilihan. Sebutan wilayah Malaysia belum disemak manusia. Guru boleh memasukkan rakaman Bahasa Melayu Malaysia yang telah disemak.</p><form id="audio-form">${selectField('Teks yang dibaca','audio-text',audioTexts().map(t=>[t,t.length>100?t.slice(0,100)+'…':t]),INTRO)}<div class="field"><label for="audio-file">Fail rakaman (MP3 / WAV / OGG, maksimum 8 MB)</label><input type="file" id="audio-file" accept="audio/*" required></div><div class="btn-row"><button type="submit" class="primary">Simpan rakaman</button>${btn('preview-audio','Dengar teks','outline','type="button"')}${btn('remove-audio','Padam rakaman sendiri','outline','type="button"')}</div></form><p class="help">Rakaman sendiri diutamakan, diikuti suara peranti ms-MY dan klip Melayu disertakan. Rakaman disimpan dalam IndexedDB peranti ini; simpan salinan fail asal sendiri.</p></div>`;}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000);}
function exportCSV(list=data.sessions){const header=['ID sesi','Nama','Kelas','Tarikh sesi','Peringkat','Cabaran','Kemahiran','Jawapan pertama','Bilangan percubaan','Jawapan-jawapan','Ketepatan perkataan','Bukti perkataan','Alasan pertama','Alasan akhir','Percubaan alasan','Ketepatan alasan','Petunjuk','Contoh ditunjukkan','Kuasa cabaran','Semua kuasa sesi','Ayat','Kaedah jawapan','Status semakan','Rubrik imbuhan','Rubrik makna','Rubrik ayat','Tahap bantuan','Ulasan rubrik','Bintang permainan','Masa peringkat ms','Jumlah masa aktif ms','Selesai','TP guru','Tarikh TP','Ulasan guru','Jenis rekod','Jenis permainan','Masa cabaran ms','Digit diperoleh','Status misi akhir','Status sijil'];const rows=[header];for(const s of list){const records=[...Object.values(s.records).map(r=>({...r,recordKind:'Teras'})),...(s.practice||[]).map(r=>({...r,recordKind:'Ulang kaji'}))];if(!records.length)records.push({recordKind:'Sesi belum menjawab'});for(const r of records)rows.push([s.id,s.name,s.className,s.createdAt,r.level,r.id,r.skill,r.firstAnswer,r.attempts,r.answers?.join(' | '),r.wordCorrect===null?'Belum dinilai':r.wordCorrect,r.wordEvidence||r.evidence,r.firstReason,r.reason,r.reasonAttempts,r.reasonCorrect===null?'Semakan guru':r.reasonCorrect,r.hints,r.shownExample,r.powers?.join('|'),JSON.stringify(s.powerLog),r.sentence,r.mode,r.review?.status,...(r.review?.criteria||['','','']),r.review?.support,r.review?.notes,r.gameStars,s.levelMs[r.level]||0,s.activeMs,r.complete,s.teacher?.tp,s.teacher?.date,s.teacher?.notes,r.recordKind,r.gameType,r.activeMs,s.earnedCodes?.map(d=>d??'—').join(' '),s.finalMission?.status,certificateEligible(s)?'Tersedia':'Belum tersedia']);}download('OPS-ImAn-rekod.csv','\uFEFF'+rows.map(row=>row.map(csvCell).join(',')).join('\r\n'),'text/csv;charset=utf-8');}
function printOptions(){const selected=data.sessions.find(s=>s.id===printSessionId)||null;return {ink,name:selected?.name||'',className:selected?.className||'',content:{items:currentItems(),words:words(),curriculum:data.settings.curriculum},session:selected};}
function printReport(s){const html=`<!doctype html><html lang="ms"><head><meta charset="utf-8"><title>Laporan OPS ImAn</title><style>@page{size:A4 landscape;margin:12mm}body{font:12px Arial;color:#183459}h1{font-size:26px}table{border-collapse:collapse;width:100%}td,th{border:1px solid #999;padding:6px;text-align:left}tr{break-inside:avoid}button{padding:12px;font-size:18px}@media print{button{display:none}}</style></head><body><button onclick="print()">Cetak / Simpan sebagai PDF</button><h1>OPS ImAn · Laporan bukti pembelajaran</h1><h2>${e(s.name)} · ${e(s.className)}</h2><p>${dateText(s.createdAt)} · Bintang permainan: ${s.stars} · Masa aktif: ${clockText(s.activeMs)} · Peringkat selesai: ${s.completedLevels.join(', ')||'Belum'}</p><p>SK: ${e(data.settings.curriculum.sk)}<br>SP: ${e(data.settings.curriculum.sp)}</p><p>TP guru: ${s.teacher?.tp?'TP'+s.teacher.tp:'Belum ditentukan'} · Tarikh: ${e(s.teacher?.date||'—')}<br>Ulasan: ${e(s.teacher?.notes||'—')}</p><p>TP tidak ditentukan daripada bintang, masa atau nombor peringkat.</p><table><thead><tr><th>Kod</th><th>Jawapan pertama / cubaan</th><th>Bukti bahasa</th><th>Alasan</th><th>Bantuan</th><th>Ayat / semakan</th></tr></thead><tbody>${Object.values(s.records).map(r=>`<tr><td>${r.id}</td><td>${e(r.firstAnswer||'—')}<br>${r.attempts}</td><td>${e(r.wordEvidence||r.evidence||'Dalam proses')}</td><td>${e(r.reason||'—')}<br>${r.reasonCorrect===null?'Menunggu semakan':r.reasonCorrect?'Betul':''}</td><td>${r.hints} petunjuk · ${r.powers.map(p=>POWER[p]?.name).join(', ')}${r.shownExample?' · Contoh':''}</td><td>${e(r.sentence||'—')}<br>${e(r.review?.status||'')} ${e(r.review?.notes||'')}</td></tr>`).join('')}</tbody></table><p>Masa peringkat: ${LEVELS.map(l=>`P${l.id} ${clockText(s.levelMs[l.id]||0)}`).join(' · ')}</p></body></html>`;const w=window.open('','_blank');if(!w){notify('Benarkan tetingkap cetakan dalam pelayar.');return;}w.document.write(html);w.document.close();}
let pauseFrom=null;
function pause(){pauseFrom=modal==='question'?'question':null;stopAudio();showModal('pause',`${dialogHead('Misi dijeda',false)}<p>Kemajuan kamu disimpan. Ambil masa yang kamu perlukan.</p><div class="btn-row">${btn('resume-pause','Sambung misi','primary')}${btn('map','Ke peta','outline')}${btn('controls','Tukar kawalan','outline')}</div><label class="check-row" style="margin-top:25px"><input id="quick-music" type="checkbox" ${data.settings.music?'checked':''}> Muzik latar lembut</label><label for="quick-volume" style="font-size:18px;margin-top:15px">Kelantangan</label><input id="quick-volume" type="range" min="0" max="1" step=".05" value="${data.settings.volume}" style="width:100%">`);save();}
function resumePause(){if(pauseFrom==='question'&&qstate){renderQuestion();}else closeModal();pauseFrom=null;lastTick=performance.now();}
function choosePractice(){if(!session){go('setup');return;}const missed=Object.values(session.records).filter(r=>r.attempts>1||r.hints||r.review?.status==='revise');showModal('review',`${dialogHead('Misi ulang kaji')}<p>${missed.length?'Mari cuba lagi dengan pengalaman baharu.':'Belum ada kesilapan direkod. Kamu boleh berlatih perkataan sasaran guru.'}</p><div class="tutorial-steps">${missed.map(r=>btn('review-item',`${r.id} · ${e(itemBy(r.id)?.answer)}`,'outline',`data-id="${r.id}"`)).join('')}${btn('target-practice','Latihan perkataan sasaran','primary')}</div>`);}
function startWordPractice(base,enrichment=false){if(!session){go('setup');notify('Isi nama dan kelas untuk merekod latihan.');return;}const w=enrichment?ENRICHMENT.find(w=>w.word===base):words().find(w=>w.base===base);if(!w)return;openQuestion({id:`LATIHAN-${w.word}`,level:1,index:1,skill:'Memahami',action:w.action,prompt:`Kata dasar: ${w.base}. Pilih perkataan berimbuhan awalan.`,choices:[w.base,w.word],answer:w.word,accepted:[w.word],hint:'Lihat gambar. Cari perkataan yang mempunyai imbuhan awalan.',explanation:w.note,type:'choice'},true);}
function targetPractice(){if(!session){go('setup');return;}showModal('targets',`${dialogHead('Latihan perkataan sasaran')}<div class="tutorial-steps">${words().filter(w=>data.settings.targets.includes(w.word)).map(w=>btn('word-practice',`${e(w.base)} → ?`,'outline',`data-word="${e(w.base)}"`)).join('')||'<p>Pilih perkataan sasaran dalam tetapan guru dahulu.</p>'}</div>`);}
function updateMusic(){const enabled=data.settings.music&&session?.audio!==false&&page==='game'&&!document.hidden&&(!modal||modal==='question');if(!enabled){clearInterval(musicTimer);musicTimer=null;if(musicGain&&musicCtx)musicGain.gain.setTargetAtTime(0,musicCtx.currentTime,.15);return;}if(musicTimer)return;try{musicCtx??=new(window.AudioContext||window.webkitAudioContext)();musicGain??=musicCtx.createGain();musicGain.connect(musicCtx.destination);musicCtx.resume();const note=()=>{const t=musicCtx.currentTime;musicGain.gain.setTargetAtTime(data.settings.volume*(isVoicePlaying()?.06:.25),t,.08);const o=musicCtx.createOscillator(),g=musicCtx.createGain();o.type='sine';o.frequency.value=[261.63,329.63,392,329.63,293.66,349.23,440,349.23][musicStep++%8];g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.11,t+.12);g.gain.exponentialRampToValueAtTime(.001,t+1.5);o.connect(g).connect(musicGain);o.start(t);o.stop(t+1.6);};musicTimer=setInterval(note,1800);note();}catch{}}
async function clickAction(action,b){
 if(action.startsWith('activity-')){handleActivity(action.slice(9),b);return;}
 switch(action){
 case 'codes':showCodes();break;case 'codes-back':restoreCodes();break;case 'final':showFinal();break;case 'code-digit':setCodeDigit(b.dataset.digit);break;case 'code-erase':eraseCode();break;case 'code-clear':session.finalMission.draft=Array(6).fill('');session.finalMission.selected=0;save();showFinal();break;case 'code-open':openSuccessChest();break;
  case 'home':go('home');break;case 'new':go('setup');break;case 'map':session?go('map'):go('setup');break;case 'library':go('library');break;case 'teacher':go('teacher');break;case 'print':printSessionId=session?.id||null;go('print');break;case 'print-session-codes':await downloadSessionCodes(printOptions());break;case 'overall':go('summary');break;
  case 'resume':if(session)startLevel(session.level);break;case 'level':if(!session){go('setup');break;}if(missionStatus(session,Number(b.dataset.level)).state==='locked'){notify('Selesaikan misi sebelumnya dahulu.');break;}startLevel(Number(b.dataset.level));break;
  case 'speak':speak(b.dataset.text,{force:true});break;case 'toggle-audio':session.audio=!session.audio;stopAudio();render();save();break;
  case 'tutorial':showTutorial();break;case 'tutorial-wrong':chime(false);notify('Belum tepat. Perkataan membaca mempunyai imbuhan awalan mem-.');speak(audioScripts().wrong);break;
  case 'tutorial-correct':chime(true);showModal('tutorial-done',`${dialogHead('Kamu sedia untuk misi!',false)}<div class="notice success">${icon('star')} Betul! membaca mempunyai imbuhan awalan.</div><p>Setiap cabaran membuka laluan. Kumpulkan empat petunjuk sebelum ke tamat.</p>${btn('tutorial-finish','Mari bermain '+icon('arrow'),'primary')}`);speak(audioScripts().correct);break;
  case 'tutorial-finish':closeModal();if(!session)go('setup');else if(page==='game')render();else go('map');break;
  case 'close':if(modal==='codes')restoreCodes();else closeModal();break;case 'pause':pause();break;case 'resume-pause':resumePause();break;case 'controls':controlsDialog();break;case 'maze-camera':mazeCamera=!mazeCamera;render();break;case 'city-guide':showModal('city-guide',`${dialogHead(LEVELS[session.level-1].name)}<img class="city-guide-art" src="${art('location-'+session.level)}" alt="Lokasi misi"><p>${e(LEVELS[session.level-1].subtitle)} · Empat cabaran bahasa.</p><p class="help">Ikut laluan dan nombor 1–4. Bangunan serta perabot ialah sempadan. Pilih objek untuk menuju cabaran.</p><a class="station-preview-link" href="station-preview.html" target="_blank" rel="noopener">Lihat pratonton keenam-enam stesen ↗</a>`);break;
  case 'camera-retry':if(session?.control==='hand'){closeModal();activateHands();}break;
  case 'control-select':if(!session)break;session.control=b.dataset.control;closeModal();stopHands();render();save();if(session.control==='hand')activateHands();else if(pauseFrom==='question'&&qstate){renderQuestion();pauseFrom=null;}break;
  case 'mouse':if(session){session.control='mouse';save();}stopHands();if(modal==='camera-error'||modal==='controls')closeModal();render();if(qstate&&pauseFrom==='question'){renderQuestion();pauseFrom=null;}notify('Tetikus dan sentuhan aktif. Kemajuan dikekalkan.');break;
  case 'calibrate':notify(calibrateHand()?'Kanta dikalibrasi. Gerakkan jari untuk menuding.':'Tunjukkan jari telunjuk kepada kamera dahulu.');break;
  case 'answer':answer(b.dataset.answer);break;case 'reason-answer':answer(b.dataset.answer,true);break;
  case 'oral-reason':{const r=recordFor();r.reason='Alasan diberi secara lisan kepada guru';r.reasonMode='oral';r.reasonCorrect=null;completeQuestion(false);break;}
  case 'question-next':questionNext();break;case 'power':usePower(b.dataset.power);break;
  case 'example':recordFor().shownExample=true;renderQuestion();speak(qstate.item.explanation);save();break;
  case 'compose-mode':qstate.composeMode=b.dataset.mode;recordFor().composeMode=qstate.composeMode;renderQuestion();save();break;
  case 'add-token':qstate.tokens.push(Number(b.dataset.token));recordFor().tokens=qstate.tokens;renderQuestion();save();break;
  case 'remove-token':qstate.tokens.splice(Number(b.dataset.token),1);recordFor().tokens=qstate.tokens;renderQuestion();save();break;
  case 'select-picture':qstate.selectedAction=b.dataset.picture;recordFor().selectedAction=qstate.selectedAction;renderQuestion();save();break;
  case 'submit-compose':{const r=recordFor(),q=qstate;const text=q.composeMode==='cards'?q.tokens.map(k=>q.item.cards[k]).join(' '):q.draft.trim();if(!text&&q.composeMode!=='oral'){notify('Bina ayat kamu dahulu atau pilih Jawab lisan.');break;}r.sentence=text;r.mode=q.composeMode;r.firstAnswer??=text||'Jawapan lisan';r.attempts++;r.answers.push(text||'Jawapan lisan');r.wordCorrect=null;r.selectedAction=q.selectedAction;r.review={status:'pending',criteria:['','',''],support:'Belum dinilai',notes:''};completeQuestion(true);break;}
  case 'continue-session':session.cycleCount=0;closeModal();save();break;
  case 'safe':{const m=mazeNow(),done=solvedIndices();session.positions[session.level]={...(done.length?m.points[done.at(-1)].gate:m.start)};drawMaze();save();notify('Kembali ke titik selamat. Jawapan kamu dikekalkan.');break;}
  case 'badges':badgesDialog();break;case 'review':choosePractice();break;case 'review-item':openQuestion(itemBy(b.dataset.id),true);break;case 'target-practice':targetPractice();break;case 'word-practice':startWordPractice(b.dataset.word);break;case 'enrich':startWordPractice(b.dataset.word,true);break;
  case 'replay':{const prev=session;session={...structuredClone(prev),id:crypto.randomUUID(),createdAt:new Date().toISOString(),completedAt:null,certificate:null,finalMission:null,earnedCodes:[],levelRewards:[],positions:{},records:{},completedLevels:[],practice:[],powerLog:[],stars:0,activeMs:0,levelMs:{},cycleCount:0,powers:{hint:4,radio:4,path:6,two:3,double:2},teacher:{tp:'',date:'',notes:''}};syncMissionProgress(session);data.sessions.push(session);startLevel(prev.level);notify('Sesi baharu bermula. Rekod sesi terdahulu dikekalkan.');break;}
  case 'certificate-view':showCertificate(data.sessions.find(s=>s.id===b.dataset.id)||certificateSession());break;
  case 'certificate-download':await exportCertificatePDF();break;
  case 'certificate-print':{const details=saveCertificateForm();if(details&&!printCertificate(details,{ink:details.ink}))notify('Benarkan tetingkap baharu untuk mencetak sijil.');break;}
  case 'certificate-voice':if(!certificateMuted)speak(CERTIFICATE_VOICE,{force:true});break;
  case 'teacher-tab':teacherTab=b.dataset.tab;render();break;case 'record':selectedRecord=b.dataset.id;render();$('.record-detail')?.scrollIntoView({behavior:'smooth'});break;
  case 'resume-record':session=data.sessions.find(s=>s.id===b.dataset.id);startLevel(session.level);break;
  case 'csv':exportCSV();break;case 'backup':download('OPS-ImAn-sandaran.json',JSON.stringify(data,null,2),'application/json');break;case 'restore':$('#restore-file').click();break;
  case 'delete-session':showModal('confirm-delete',`${dialogHead('Padam rekod sesi ini?')}<p>Semua jawapan dan ulasan sesi ini akan dipadam daripada peranti. Eksport dahulu jika perlu.</p><div class="btn-row">${btn('confirm-delete','Padam sesi','danger',`data-id="${b.dataset.id}"`)}${btn('close','Batal','outline')}</div>`);break;
  case 'confirm-delete':data.sessions=data.sessions.filter(s=>s.id!==b.dataset.id);if(session?.id===b.dataset.id)session=null;selectedRecord=null;save();closeModal();render();notify('Rekod sesi dipadam.');break;
  case 'print-report':printReport(data.sessions.find(s=>s.id===b.dataset.id));break;case 'print-preview':if(!openPrint(b.dataset.id,printOptions()))notify('Benarkan tetingkap baharu untuk membuka pratonton cetakan.');break;case 'print-certificate':showCertificate(session);break;
  case 'reset-item':delete data.overrides[editItem];save();render();notify('Kandungan asal dipulihkan.');break;case 'export-content':download('OPS-ImAn-bank-kandungan.json',JSON.stringify({items:currentItems(),words:words(),curriculum:data.settings.curriculum},null,2),'application/json');break;
  case 'preview-audio':speak($('#audio-text').value,{force:true});break;case 'remove-audio':await removeRecording($('#audio-text').value);notify('Rakaman sendiri dipadam. Audio lalai digunakan.');break;
  case 'info':showModal('info',`${dialogHead('Tentang OPS ImAn')}<p>Permainan imbuhan awalan untuk Tahun 2 KSSR. Enam peringkat perkembangan kemahiran bukan enam Tahap Penguasaan.</p><p class="help">${e(data.settings.curriculum.sk)}<br>${e(data.settings.curriculum.sp)}</p><div class="notice">Kamera diproses pada peranti. Tiada video murid dirakam. Nama, jawapan dan kemajuan disimpan dalam pelayar ini.</div><p class="help">Audio sintesis Melayu disediakan; varian Malaysia belum disemak manusia. Guru boleh menggantikan audio dengan rakaman sendiri.</p><div class="btn-row">${btn('cache-offline','Sediakan aset luar talian','primary')}${btn('kit-guide','Panduan kit','outline')}</div><p id="offline-progress" class="help">Muat turun aset dahulu untuk penggunaan luar talian. Ketersediaan bergantung pada ruang simpanan pelayar.</p>`);break;
  case 'kit-guide':showModal('guide',`${dialogHead('Kit beg bimbit OPS ImAn')}<p><b>30 minit:</b> 3 minit pengenalan digital, 18 minit maze, 9 minit aktiviti maujud.</p><div class="tutorial-steps"><div class="tutorial-step"><span class="number">1</span><div><strong>Cetak dan potong</strong><small>Gunakan A4/A3, cetak skala 100%, potong pada garisan putus-putus.</small></div></div><div class="tutorial-step"><span class="number">2</span><div><strong>Lamina dan pasang</strong><small>Lipat papan, gunakan pelekat boleh tanggal pada kad dan token.</small></div></div><div class="tutorial-step"><span class="number">3</span><div><strong>Susun dalam poket</strong><small>Kad misi, kad gambar, kata dasar/awalan, bina ayat, token, lembaran dan panduan guru.</small></div></div></div><p class="help">Aktiviti individu: pilih gambar, padan kata, susun ayat dan gerakkan token. Enam peringkat boleh diselesaikan dalam beberapa sesi.</p>${btn('print','Buka pusat cetakan','primary')}`);break;
  case 'cache-offline':await prepareOffline();break;
 }
}
document.addEventListener('click',event=>{if(performance.now()<suppressActivityClick)return;const b=event.target.closest('button[data-action],button[data-dir],[data-station-target]');if(!b||b.disabled)return;if(b.dataset.stationTarget!==undefined){navigateToStation(Number(b.dataset.stationTarget));return;}if(b.dataset.dir){move(b.dataset.dir);return;}clickAction(b.dataset.action,b).catch(err=>{console.error(err);notify('Tindakan belum berjaya. '+err.message);});});
document.addEventListener('pointerdown',event=>{const b=event.target.closest('[data-dir]');if(!b||b.disabled)return;event.preventDefault();move(b.dataset.dir);clearInterval(holdTimer);holdTimer=setInterval(()=>move(b.dataset.dir),260);b.classList.add('held');});
['pointerup','pointercancel','blur'].forEach(type=>window.addEventListener(type,()=>{clearInterval(holdTimer);$$('.held').forEach(b=>b.classList.remove('held'));}));
document.addEventListener('keydown',event=>{if(event.key==='Tab'&&modal){const list=$$('.dialog button:not(:disabled),.dialog input,.dialog textarea,.dialog select,.dialog a[href],.dialog summary').filter(el=>!el.hidden&&el.getClientRects().length);const first=list[0],last=list.at(-1);if(event.shiftKey&&(document.activeElement===first||document.activeElement===$('.dialog'))){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}return;}if(/INPUT|SELECT|TEXTAREA/.test(event.target.tagName))return;const dir={ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right',w:'up',s:'down',a:'left',d:'right'}[event.key];if(dir&&(!modal&&page==='game'||modal==='tutorial')){event.preventDefault();move(dir);}if(event.key==='Escape'){if(page==='game'&&!modal)pause();else if(modal==='pause')resumePause();else if(modal==='codes')restoreCodes();else if(modal!=='question'&&modal!=='level-summary')closeModal();}});
document.addEventListener('input',event=>{const el=event.target;if(el.matches('[data-code-slot]')){const value=el.value.replace(/[^0-9]/g,'').slice(-1),index=Number(el.dataset.codeSlot);session.finalMission.draft[index]=value;el.value=value;session.finalMission.selected=value?Math.min(5,index+1):index;save();if(value)document.querySelector('[data-code-slot="'+session.finalMission.selected+'"]')?.focus();}if(el.id==='activity-draft'&&qstate){qstate.activity.draft=el.value;save();}if(el.id==='sentence-input'&&qstate){qstate.draft=el.value;recordFor().draft=el.value;save();}if(el.id==='hand-sensitivity'){data.settings.sensitivity=Number(el.value);handSettings({sensitivity:data.settings.sensitivity});save();}if(el.id==='quick-volume'){data.settings.volume=Number(el.value);applySettings();save();}});
document.addEventListener('keydown',event=>{const target=event.target.closest?.('[data-station-target]');if(target&&['Enter',' '].includes(event.key)){event.preventDefault();navigateToStation(Number(target.dataset.stationTarget));}});
document.addEventListener('change',event=>{const el=event.target;if(el.id==='activity-typing'&&qstate){qstate.activity.typing=el.checked;renderQuestion();save();}if(el.id==='certificate-mute'){certificateMuted=el.checked;const s=certificateSession();if(s?.certificate)s.certificate.silent=certificateMuted;if(certificateMuted)stopAudio();$$('[data-action=certificate-voice]').forEach(b=>b.disabled=certificateMuted);save();}if(el.id==='certificate-ink'){const details=saveCertificateForm();if(details){certificateSession().certificate.ink=el.checked;save();$('#certificate-preview').innerHTML=certificateSVG(details,{ink:el.checked});}}if(el.id==='print-session'){printSessionId=el.value||null;render();}if(el.id==='ink-mode'){ink=el.checked;render();}if(el.id==='item-select'){editItem=el.value;render();}if(el.id==='word-select'){editWord=el.value;render();}if(el.id==='quick-music'){data.settings.music=el.checked;applySettings();save();}if(el.id==='restore-file')restoreFile(el.files[0]);});
document.addEventListener('submit',async event=>{event.preventDefault();const form=event.target,f=new FormData(form);try{
 if(form.id==='setup-form'){newSession(f);}
 else if(form.id==='certificate-form'){if(saveCertificateForm()){showCertificate(certificateSession(),false);notify('Pembetulan sijil disimpan.');}}
 else if(form.id==='settings-form'){const prior=data.settings;data.settings={...prior,teacherName:String(f.get('teacherName')||'').trim(),schoolName:String(f.get('schoolName')||'').trim(),mode:f.get('mode'),startLevel:Number(f.get('startLevel')),limit:Number(f.get('limit')),font:Number(f.get('font')),rate:Number(f.get('rate')),volume:Number(f.get('volume')),music:f.has('music'),easy:f.has('easy'),reduced:f.has('reduced'),targets:f.getAll('targets'),assist:f.getAll('assist'),enrichment:f.getAll('enrichment'),curriculum:{sk:f.get('sk'),sp:f.get('sp'),document:f.get('document'),confirmed:f.has('curriculum-confirmed')}};if(data.settings.mode==='enrichment'&&data.settings.startLevel===1)data.settings.startLevel=4;if(session){session.assist=[...data.settings.assist];session.limit=data.settings.limit;}save();render();notify('Tetapan disimpan.');}
 else if(form.id==='assessment-form'){const s=data.sessions.find(s=>s.id===form.dataset.id);s.teacher={tp:f.get('tp'),date:f.get('assessment-date'),notes:f.get('teacher-notes')};save();notify('Pertimbangan guru disimpan.');}
 else if(form.classList.contains('review-form')){const s=data.sessions.find(s=>s.id===form.dataset.session),r=s.records[form.dataset.item];r.review={criteria:[0,1,2].map(k=>f.get('rubric-'+k)),support:f.get('support'),status:f.get('review-status'),notes:f.get('review-notes'),at:new Date().toISOString()};if(r.mode)r.sentence=f.get('response');else r.reason=f.get('response');if(r.mode)r.accuracy=r.review.status==='pending'?null:r.review.status==='accepted';if(r.reasonMode==='oral')r.reasonCorrect=r.review.status==='pending'?null:r.review.status==='accepted';save();notify('Semakan rubrik disimpan tanpa mengubah bintang atau TP.');}
 else if(form.id==='content-form'){const original=itemBy(form.dataset.id),choices=String(f.get('choices')).split('\n').map(s=>s.trim()).filter(Boolean),answer=String(f.get('answer')).trim();if(['choice','match','blank'].includes(original.type)&&(choices.length<2||choices.length>3||!choices.includes(answer)))throw new Error('Sediakan 2–3 pilihan dan pastikan jawapan diterima terdapat dalam pilihan.');const update={prompt:f.get('prompt'),action:f.get('action'),choices,answer,accepted:answer.split('|'),explanation:f.get('explanation'),hint:f.get('hint')};if(original.type==='reason'){update.reason=f.get('reason');update.reasonChoices=String(f.get('reasonChoices')).split('\n').map(s=>s.trim()).filter(Boolean);if(update.reasonChoices.length<2||update.reasonChoices.length>3||!update.reasonChoices.includes(update.reason))throw new Error('Alasan betul mesti terdapat dalam 2–3 pilihan alasan.');}if(original.type==='sentence')update.cards=String(f.get('cards')).split('\n').map(s=>s.trim()).filter(Boolean);validateItem({...original,...update});data.overrides[original.id]=update;save();notify('Cabaran disimpan. Semak atau gantikan audio bagi teks baharu.');}
 else if(form.id==='word-form'){data.wordOverrides[form.dataset.base]={word:f.get('word'),prefix:f.get('prefix'),action:f.get('word-action'),note:f.get('note')};save();notify('Bank perkataan dikemas kini.');}
 else if(form.id==='audio-form'){await saveRecording(f.get('audio-text'),$('#audio-file').files[0]);notify('Rakaman disimpan pada peranti ini.');}
 }catch(err){notify(err.message);}});
async function restoreFile(file){if(!file)return;try{if(file.size>10*1024*1024)throw new Error('Fail sandaran terlalu besar.');const imported=JSON.parse(await file.text());if(!Array.isArray(imported.sessions)||!imported.settings)throw new Error('Format sandaran tidak sah.');let count=0;for(const s of imported.sessions){if(typeof s.name!=='string'||typeof s.className!=='string'||!s.records||!s.positions||!Array.isArray(s.completedLevels)||!s.powers||!s.levelMs||!['boy','girl','hijab'].includes(s.avatar)||!Number.isFinite(s.activeMs))throw new Error('Struktur sesi tidak sah.');if(!data.sessions.some(x=>x.id===s.id)){migrateProgress({saveVersion:imported.saveVersion,sessions:[s]});data.sessions.push(s);count++;}}save();render();notify(`${count} sesi dipulihkan. Tetapan semasa dikekalkan.`);}catch(err){notify('Sandaran tidak dapat dipulihkan: '+err.message);}}
document.addEventListener('visibilitychange',()=>{wasHidden=document.hidden;lastTick=performance.now();if(document.hidden){clearInterval(holdTimer);stopAudio();save();}updateMusic();});
window.addEventListener('beforeunload',()=>{save();stopHands();});
setInterval(()=>{const now=performance.now(),dt=Math.min(now-lastTick,1500);lastTick=now;const active=page==='game'&&session&&!session.finalMission?.complete&&!document.hidden&&(!modal||modal==='question')&&(session.control!=='hand'||handTracked());if(active){session.activeMs+=dt;if(modal==='question'&&qstate&&!qstate.practice&&!recordFor().complete)recordFor().activeMs=(recordFor().activeMs||0)+dt;session.levelMs[session.level]=(session.levelMs[session.level]||0)+dt;if($('#timer'))$('#timer').textContent=clockText(session.activeMs);if(now-lastSave>4000){lastSave=now;save();}}if(musicGain&&musicCtx)musicGain.gain.setTargetAtTime(data.settings.volume*(active?(isVoicePlaying()?.06:.25):0),musicCtx.currentTime,.12);},250);
let registration;
async function prepareOffline(){if(!('serviceWorker' in navigator)){notify('Pelayar ini tidak menyokong simpanan luar talian.');return;}try{registration??=await navigator.serviceWorker.register('./sw.js');await navigator.serviceWorker.ready;const worker=registration.active||navigator.serviceWorker.controller;if(!worker)throw new Error('Muat semula halaman untuk mengaktifkan simpanan.');worker.postMessage({type:'CACHE_ALL'});if($('#offline-progress'))$('#offline-progress').textContent='Sedang memuat turun model tangan, audio, ilustrasi dan PDF…';}catch(err){notify(err.message);}}
if('serviceWorker' in navigator){navigator.serviceWorker.register('./sw.js').then(r=>registration=r).catch(()=>{});navigator.serviceWorker.addEventListener('message',ev=>{const d=ev.data;if(d.type==='CACHE_PROGRESS'){const msg=d.complete?'Aset luar talian tersedia pada pelayar ini.':`Memuat turun aset: ${d.done}/${d.total}`;if($('#offline-progress'))$('#offline-progress').textContent=msg;if(d.complete)notify(msg);}if(d.type==='CACHE_ERROR')notify('Sebahagian aset belum disimpan. Cuba lagi ketika ada internet.');});}
await initAudio({enabled:true,rate:data.settings.rate,volume:data.settings.volume,notify});render();save();

function renderQuestion(){
 if(!qstate.item.gameType){renderLegacyQuestion();return;}
 const q=qstate,i=q.item,r=recordFor(),done=q.feedback==='correct',wrong=q.feedback==='wrong';
 const result=`<div class="activity-result">${e(i.base)} → ${wordParts(i.answer,i.prefix)}</div>`;
 showModal('question',`<div class="dialog-head"><span class="pill">${i.id} · ${e(GAME_NAMES[i.level-1])}${q.practice?' · Ulang kaji':''}</span><div class="btn-row">${btn('codes','Kad kod','small outline')}${btn('pause',icon('pause'),'icon-btn','aria-label="Jeda cabaran"')}</div></div><div class="question-layout"><div>${questionImage(i,`question-image ${q.radio?'highlight':''}`)}${done?result:''}<p class="help center">${e(LEVELS[i.level-1].mission)}</p></div><div><div class="btn-row"><p class="question-text">${e(done?'Bagus! Kamu berjaya!':i.prompt)}</p>${audioBtn(i.prompt)}</div>${!done||i.type==='search'?activityView(i,q.activity,{done,two:q.two,guidance:session.mode==='guidance',enrichment:session.mode==='enrichment'}):''}${wrong?`<div class="feedback wrong" role="status"><strong>${icon('close')} Belum tepat. Mari cuba lagi.</strong><p>${e(i.hint)}</p></div>`:''}${done?`<div class="feedback correct" role="status"><strong>★ Betul! Usaha kamu dihargai.</strong><p>${e(i.sentence)}</p>${audioBtn(i.explanation)}${btn('question-next',q.practice?'Selesai ulang kaji':'Teruskan misi '+icon('arrow'),'primary')}</div>`:''}${!done&&q.hint?`<div class="hint-box">${icon('search')} ${e(i.hint)} ${audioBtn(i.hint)}</div>`:''}${!done&&r.shownExample?`<div class="notice">${e(i.explanation)} ${audioBtn(i.explanation)}</div>`:''}</div></div>${!done?`<div class="quiz-powers">${['hint','radio','two','double'].map(powerButton).join('')}</div><div class="btn-row">${btn('example','Lihat contoh bersama guru','small outline')}<small>Semak apabila jawapan kamu siap.</small></div>`:''}`,true);
 $('.dialog').classList.add('activity-dialog');
 $$('[data-drag-card]').forEach(el=>el.classList.add('drag-card'));
}
function handleActivity(action,b){
 if(modal!=='question'||!qstate||qstate.feedback==='correct')return;
 const q=qstate,i=q.item,a=q.activity,r=recordFor();let speech;
 if(action==='submit'){
  const value=activityAnswer(i,a);if(!value.trim()){notify('Sediakan jawapan dahulu, kemudian tekan Semak.');return;}
  r.attempts++;r.firstAnswer??=value;r.answers.push(value);r.wordCorrect=activityCorrect(i,a);r.gameType=i.gameType;
  if(i.type==='sentence'){r.sentence=value;r.mode='cards';}
  if(r.wordCorrect){r.wordEvidence=assessEvidence(r.attempts,r.hints,r.shownExample);completeQuestion(false);return;}
  r.hints++;q.hint=true;q.feedback='wrong';chime(false);renderQuestion();save();speak([audioScripts().wrong,i.hint]);return;
 }
 q.feedback=null;
 if(action==='match-a'){a.matchSelected=true;speech=i.base;}
 if(action==='match-b'&&a.matchSelected){a.selection=b.dataset.value;speech=a.selection;}
 if(action==='cell'){const index=Number(b.dataset.cell);if(a.start==null||a.end!=null){a.start=index;a.end=null;}else a.end=index;}
 if(action==='piece'){const index=Number(b.dataset.index);if(!a.tokens.includes(index))a.tokens.push(index);speech=i.pieces[index];}
 if(action==='blank-slot')a.blankSelected=true;
 if(action==='blank-word'&&a.blankSelected){a.selection=b.dataset.value;speech=a.selection;}
 if(action==='card'){a.selectedCard=Number(b.dataset.index);speech=i.cards[a.selectedCard];}
 if(action==='slot'){const slot=Number(b.dataset.slot);if(a.selectedCard!=null)placeCard(a,a.selectedCard,slot);else if(a.slots[slot]!=null){a.selectedCard=a.slots[slot];speech=i.cards[a.selectedCard];}}
 if(action==='reset'){q.activity=newActivity(i);r.activity=q.activity;}
 if(action==='undo'){
  if(i.type==='scramble')a.tokens.pop();else if(i.type==='search'){a.start=null;a.end=null;}else if(i.type==='sentence'){const index=a.slots.findLastIndex(x=>x!=null);if(index>=0)a.slots[index]=null;a.selectedCard=null;}else a.selection=null;
 }
 renderQuestion();save();if(speech)speak(speech);
}
function codeCards(s,compact=false){return `<div class="code-strip ${compact?'compact':''}">${LEVELS.map((l,i)=>`<div class="code-card ${s.earnedCodes?.[i]==null?'pending':''}"><small>Stesen ${i+1}</small><img src="assets/v2/location-${i+1}.png" alt="${e(l.name)}"><strong>${s.earnedCodes?.[i]??'—'}</strong><small>${s.earnedCodes?.[i]==null?'Belum diperoleh':'✓ Selesai'}</small></div>`).join('')}</div>`;}
function finalBanner(){if(!session)return '';return `${allStationsComplete(session)?'<div class="final-route" aria-label="Laluan ke Pusat Kawalan"><span>↓</span> Laluan akhir</div>':''}<section class="final-banner"><h2>Pusat Kawalan OPS ImAn</h2><p>${allStationsComplete(session)?'Enam stesen selesai! Gabungkan digit mengikut urutan stesen untuk membuka Peti Kejayaan.':'Kumpul satu digit selepas empat cabaran di setiap stesen.'}</p>${codeCards(session,true)}<div class="btn-row">${btn('codes','Kad Kod Saya','gold')}${allStationsComplete(session)?btn(session.finalMission.complete?'certificate-view':'final',session.finalMission.complete?'Lihat Sijil':'Ke Peti Kejayaan','gold',session.finalMission.complete?`data-id="${session.id}"`:''):''}</div></section>`;}
let codesReturn=null;
function showCodes(){if(!session)return;codesReturn=modal;showModal('codes',`${dialogHead('Kad Kod Saya',false)}<p>Susun digit mengikut Stesen 1 hingga Stesen 6. Kamu boleh merujuk kad ini pada bila-bila masa.</p>${codeCards(session)}<div class="btn-row">${btn('codes-back','Kembali','primary')}${allStationsComplete(session)?btn('final','Ke Peti Kejayaan','gold'):''}</div>`,true);}
function restoreCodes(){if(codesReturn==='question'&&qstate)renderQuestion();else if(codesReturn==='final')showFinal();else if(codesReturn==='level-summary')finishLevel();else closeModal();codesReturn=null;}
function showFinal(){
 if(!session)return;syncMissionProgress(session);if(!allStationsComplete(session)){notify('Selesaikan empat cabaran pada setiap stesen dahulu.');return;}
 stopHands();stopAudio();if(session.finalMission.complete){showCompletion(session);return;}
 const f=session.finalMission;showModal('final',`${dialogHead('Pusat Kawalan OPS ImAn')}<div class="center"><div class="success-chest" aria-label="Peti Kejayaan">★</div><h2>Buka Peti Kejayaan</h2><p>${FINAL_INSTRUCTION} ${audioBtn(FINAL_INSTRUCTION)}</p><div class="code-inputs">${f.draft.map((digit,index)=>`<input inputmode="numeric" autocomplete="off" maxlength="1" pattern="[0-9]" aria-label="Digit Stesen ${index+1}" data-code-slot="${index}" value="${e(digit)}" class="${index===f.selected?'active-digit':''}">`).join('')}</div><div class="number-pad">${['1','2','3','4','5','6','7','8','9'].map(d=>btn('code-digit',d,'outline',`data-digit="${d}"`)).join('')}${btn('code-erase','⌫','outline','aria-label="Padam satu digit"')}${btn('code-digit','0','outline','data-digit="0"')}${btn('code-clear','Kosongkan','outline small')}</div>${f.error?`<div class="feedback wrong" role="status">✕ ${FINAL_RETRY}</div>`:''}<div class="btn-row" style="justify-content:center">${btn('codes','Lihat Kad Kod','outline')}${btn('code-open','Buka Peti','gold')}</div><p class="help">Tiada had masa. Boleh cuba lagi dan melihat kad kod.</p></div>`);save();
}
function setCodeDigit(digit){if(modal!=='final'||!/^\d$/.test(digit))return;const f=session.finalMission;f.draft[f.selected]=digit;f.selected=Math.min(5,f.selected+1);f.error=false;save();showFinal();}
function eraseCode(){if(modal!=='final')return;const f=session.finalMission;if(!f.draft[f.selected]&&f.selected>0)f.selected--;f.draft[f.selected]='';f.error=false;save();showFinal();}
function openSuccessChest(){if(modal!=='final')return;const f=session.finalMission;if(!unlockFinal(session,f.draft.join(''))){f.error=true;save();showFinal();chime(false);speak(FINAL_RETRY);return;}ensureCertificate(session,data.settings);save();showCompletion(session);if(!certificateMuted)speak(FINAL_SUCCESS);}
document.addEventListener('focusin',event=>{if(event.target.matches('[data-code-slot]')){session.finalMission.selected=Number(event.target.dataset.codeSlot);$$('[data-code-slot]').forEach(el=>el.classList.toggle('active-digit',el===event.target));}});
let activityDrag=null,suppressActivityClick=0;
document.addEventListener('dragstart',event=>{if(event.target.closest('[data-drag-card]'))event.preventDefault();});
document.addEventListener('pointerdown',event=>{
 if(modal!=='question'||qstate?.feedback==='correct')return;const target=event.target.closest('[data-cell],[data-drag-card]');if(!target||target.disabled)return;
 activityDrag={pointerId:event.pointerId,x:event.clientX,y:event.clientY,cell:target.dataset.cell,card:target.dataset.dragCard,moved:false,text:target.textContent};
});
window.addEventListener('pointermove',event=>{
 const d=activityDrag;if(!d||d.pointerId!==event.pointerId)return;
 if(Math.hypot(event.clientX-d.x,event.clientY-d.y)<8&&!d.moved)return;d.moved=true;
 if(d.card!=null){if(!$('.drag-ghost')){const el=document.createElement('div');el.className='drag-ghost';el.textContent=d.text;document.body.append(el);}Object.assign($('.drag-ghost').style,{left:event.clientX+12+'px',top:event.clientY+12+'px'});}
 $$('[data-slot].drag-over').forEach(el=>el.classList.remove('drag-over'));document.elementFromPoint(event.clientX,event.clientY)?.closest('[data-slot]')?.classList.add('drag-over');
});
window.addEventListener('pointerup',event=>{
 const d=activityDrag;activityDrag=null;$('.drag-ghost')?.remove();$$('.drag-over').forEach(el=>el.classList.remove('drag-over'));
 if(!d||!d.moved||!qstate||modal!=='question')return;suppressActivityClick=performance.now()+450;
 const hit=document.elementFromPoint(event.clientX,event.clientY),a=qstate.activity;
 if(d.cell!=null){const end=hit?.closest('[data-cell]');if(end){a.start=Number(d.cell);a.end=Number(end.dataset.cell);qstate.feedback=null;renderQuestion();save();}}
 if(d.card!=null){const slot=hit?.closest('[data-slot]');if(slot){placeCard(a,Number(d.card),Number(slot.dataset.slot));qstate.feedback=null;renderQuestion();save();}}
});
window.addEventListener('pointercancel',()=>{activityDrag=null;$('.drag-ghost')?.remove();});
document.addEventListener('keydown',event=>{
 if(event.target.matches('[data-cell]')&&['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(event.key)){event.preventDefault();const current=Number(event.target.dataset.cell),delta={ArrowUp:-8,ArrowDown:8,ArrowLeft:-1,ArrowRight:1}[event.key];document.querySelector('[data-cell="'+Math.max(0,Math.min(63,current+delta))+'"]')?.focus();}
});
